@theme {
      --color-parchment: oklch(96% 0.02 80);
      --color-boucle: oklch(93% 0.018 85);
      --color-oak: oklch(72% 0.05 72);
      --color-terracotta: oklch(58% 0.09 45);
      --color-walnut: oklch(22% 0.02 48);
      --color-smoke: oklch(40% 0.02 50);
    }

    @layer base {.sc-tw *{
        box-sizing: border-box;
      }.sc-tw html{
        scroll-behavior: smooth;
      }.sc-tw{
        font-family: "Inter Tight", sans-serif;
        background:
          radial-gradient(circle at top left, rgba(194,153,104,.12), transparent 22%),
          radial-gradient(circle at bottom right, rgba(150,110,84,.09), transparent 22%),
          linear-gradient(180deg, oklch(96% 0.02 80), oklch(94% 0.018 80));
        color: #221f1a;
        overflow-x: hidden;
      }.sc-tw h1,.sc-tw h2,.sc-tw h3,.sc-tw h4{
        font-family: "Cormorant Garamond", serif;
        letter-spacing: -.05em;
      }
    }

    @layer utilities {.sc-tw .atelier-window{
        mask-image:
          radial-gradient(circle at top center, black 42%, transparent 76%),
          linear-gradient(black, black);
        -webkit-mask-image:
          radial-gradient(circle at top center, black 42%, transparent 76%),
          linear-gradient(black, black);
        mask-composite: intersect;
        -webkit-mask-composite: source-in;
        border-radius: 16rem 16rem 4rem 4rem;
      }.sc-tw .glass-smoke{
        backdrop-filter: blur(15px) contrast(.95);
        -webkit-backdrop-filter: blur(15px) contrast(.95);
      }.sc-tw .silk-touch{
        position: relative;
        overflow: hidden;
        border-radius: 999px;
        background:
          linear-gradient(180deg,
            rgba(255,255,255,.92),
            rgba(241,233,219,.9));
        box-shadow:
          inset 0 1px 0 rgba(255,255,255,.9),
          0 18px 40px rgba(100,80,54,.08);
        transition:
          transform .4s cubic-bezier(.16,1,.3,1),
          box-shadow .4s ease;
      }.sc-tw .silk-touch:hover{
        transform: translateY(2px);
        box-shadow:
          inset 0 8px 20px rgba(109,84,54,.09),
          inset 0 -1px 0 rgba(255,255,255,.8);
      }.sc-tw .grain-oak{
        background-image:
          linear-gradient(rgba(255,255,255,.02), rgba(255,255,255,.02)),
          repeating-linear-gradient(
            90deg,
            rgba(102,75,48,.05) 0px,
            rgba(102,75,48,.05) 1px,
            transparent 1px,
            transparent 7px
          );
      }.sc-tw .woven-layer{
        background-image:
          linear-gradient(rgba(255,255,255,.06), rgba(255,255,255,.06)),
          repeating-linear-gradient(
            0deg,
            rgba(113,88,58,.04) 0px,
            rgba(113,88,58,.04) 1px,
            transparent 1px,
            transparent 5px
          ),
          repeating-linear-gradient(
            90deg,
            rgba(113,88,58,.04) 0px,
            rgba(113,88,58,.04) 1px,
            transparent 1px,
            transparent 5px
          );
      }.sc-tw .arch-card{
        border-radius: 10rem 10rem 2.5rem 2.5rem;
      }.sc-tw .kinetic-title span{
        display: inline-block;
        opacity: 0;
        transform: translateY(80px);
        animation: reveal .8s cubic-bezier(.16,1,.3,1) forwards;
      }.sc-tw .kinetic-title span:nth-child(2){
        animation-delay: .08s;
      }.sc-tw .kinetic-title span:nth-child(3){
        animation-delay: .16s;
      }.sc-tw .kinetic-title span:nth-child(4){
        animation-delay: .24s;
      }.sc-tw .section-rise{
        animation: rise linear both;
        animation-timeline: view();
        animation-range: entry 10% cover 40%;
      }.sc-tw .float-slow{
        animation: floaty 8s ease-in-out infinite;
      }.sc-tw .float-slower{
        animation: floaty 11s ease-in-out infinite;
      }.sc-tw .macro-track{
        scrollbar-width: none;
      }.sc-tw .macro-track::-webkit-scrollbar{
        display: none;
      }

      @keyframes reveal {to{
          opacity: 1;
          transform: translateY(0);
        }
      }

      @keyframes rise {from{
          opacity: 0;
          transform: translateY(60px) scale(.98);
        }to{
          opacity: 1;
          transform: translateY(0) scale(1);
        }
      }

      @keyframes floaty {0%,100%{
          transform: translateY(0px);
        }50%{
          transform: translateY(-12px);
        }
      }

      @keyframes zoomVideo {from{
          transform: scale(1.02);
        }to{
          transform: scale(1.12);
        }
      }.sc-tw .hero-video{
        animation:
          zoomVideo linear both;
        animation-timeline: scroll(root);
      }
